def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Defect on the last round: no future retaliation possible.
    if n >= 100:
        return 'D'

    opp_last = history[-1][1]
    me_last = history[-1][0]

    # Count opponent defections cheaply.
    opp_def = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_def += 1

    # Very short prefix: cooperate, but answer a defection immediately.
    if n < 6:
        return 'C' if opp_last == 'C' else 'D'

    # Always-defector detection: if opponent has basically never cooperated, defect.
    if opp_def >= n - 1 and n >= 8:
        return 'D'

    # Near-perfect cooperator: cooperate, but exploit in final third.
    if opp_def == 0:
        if n >= 70:
            # Occasionally defect late against a pure cooperator.
            if rng.random() < 0.35:
                return 'D'
        return 'C'

    # Recent window behavior.
    w = 12
    if w > n:
        w = n
    opp_recent_c = 0
    my_recent_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            opp_recent_c += 1
        if history[i][0] == 'C':
            my_recent_c += 1

    # Opponent currently in an all-defect streak.
    if opp_recent_c == 0:
        return 'D'

    # Opponent almost always cooperating recently: cooperate, probe rarely.
    if opp_recent_c >= w - 1:
        if n >= 70 and rng.random() < 0.2:
            return 'D'
        return 'C'

    opp_rate = opp_def / n

    # Aggressive against mostly-defecting opponents.
    if opp_rate > 0.55:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Tit-for-tat with forgiveness against moderately defecting opponents.
    if opp_last == 'D':
        # If we ourselves have defected a lot recently and opponent is recovering, cooperate.
        if my_recent_c <= w // 3 and opp_recent_c >= w // 2:
            return 'C'
        # Forgive a single defection if the opponent has otherwise been good.
        if opp_rate < 0.2 and rng.random() < 0.6:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    # If we've been exploiting a highly cooperative opponent, keep cooperating to avoid collapse.
    if opp_rate < 0.15:
        if n >= 80 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Modest exploitation against moderately cooperative opponents late.
    if n >= 80 and opp_rate < 0.35 and rng.random() < 0.15:
        return 'D'

    return 'C'
